/* Platform controls are visible only after the server confirms the owner. */
(() => {
 'use strict';
 let home=null,identity='',epoch=0,ownerStatus=null,section='users',offset=0,query='',reportStatus='open',panel=0;
 const $=id=>document.getElementById(id);
 const esc=value=>home.esc(value);
 const encode=value=>encodeURIComponent(String(value));
 const sections=[['users','Accounts'],['communities','Communities'],['reports','Reports'],['catalog','Gift catalog'],['badges','Badge definitions'],['awards','Badge awards'],['audit','Audit trail'],['health','Health']];
 function sync(){const id=home?.state.account?.id||'';if(id!==identity){identity=id;epoch++;panel++;ownerStatus=null;section='users';offset=0;query='';reportStatus='open';}}
 function guard(){sync();const e=epoch,id=identity,parent=home.guard();return ()=>e===epoch&&id===home.state.account?.id&&parent();}
 const date=value=>value?new Date(value).toLocaleString():'—';
 function fail(error){const node=$('va-error');if(node?.isConnected)node.textContent=error.message||'The request could not finish.';else home.announce(error.message||'The request could not finish.');}
 async function status(){sync();if(!identity)return;const current=guard();try{const data=await home.request('/api/admin/status');if(current()){ownerStatus=data;home.render();}}catch{if(current())ownerStatus=null;}}
 function navHTML(){sync();return ownerStatus?.isOwner?'<button class="vh-nav-item" data-home="admin-open">Administration</button>':'';}
 function accountHTML(){sync();if(ownerStatus?.isOwner)return '<button class="va-account" data-home="admin-open"><span><b>Platform administration</b><small>Verified owner · passkey confirmation required</small></span></button>';
  return ownerStatus&&!ownerStatus.ownerConfigured?'<button class="va-account" data-home="admin-owner-claim"><span><b>Owner verification request</b><small>For the intended owner: prove this account to the trusted server operator</small></span></button>':'';
 }
 async function stepUp(){
  if(Number(home.state.session?.reauthenticatedAt||0)<Date.now()-600000&&typeof home.reauthenticate==='function')await home.reauthenticate();
  if(typeof home.passkeyStepUp==='function')await home.passkeyStepUp();
  else throw Error('Confirm your password and verify a passkey in Devices and Security, then try again.');
 }
 async function claim(){
  const current=guard();try{
   await stepUp();if(!current())return;
   const data=await home.request('/api/admin/owner/claim',{});if(!current())return;
   home.showDialog('Verify this owner account','This request proves control of your current account. It does not grant administration.',`<section class="va-panel"><p>Give this private, five-minute request code to the trusted server operator. They must verify your request and bind the immutable account ID through server configuration.</p><label class="vh-field">Ownership request code<textarea id="va-owner-code" readonly rows="3" spellcheck="false">${esc(data.code)}</textarea></label><p>Account ID: <code>${esc(data.accountId)}</code></p><p>Expires ${esc(date(data.expiresAt))}. Public usernames and community roles cannot claim this access.</p><button class="vh-secondary" data-va-action="copy-claim">Copy request code</button><p class="va-error" id="va-error" role="alert"></p></section>`);
  }catch(error){if(current())fail(error);}
 }
 function pager(data){const p=data.page;if(!p)return '';return `<footer class="va-pages"><span>${p.total?`${p.offset+1}–${Math.min(p.offset+p.limit,p.total)} of ${p.total}`:'0 records'}</span><button class="vh-secondary" data-va-action="page" data-offset="${Math.max(0,p.offset-p.limit)}" ${p.offset?'':'disabled'}>Previous</button><button class="vh-secondary" data-va-action="page" data-offset="${p.offset+p.limit}" ${p.hasMore?'':'disabled'}>Next</button></footer>`;}
 function layout(){return `<section class="va-panel"><nav class="va-tabs" aria-label="Administration section">${sections.map(([key,label])=>`<button data-va-action="section" data-section="${key}" aria-current="${key===section?'page':'false'}">${label}</button>`).join('')}</nav>${['users','communities'].includes(section)?`<form data-va-form="search" class="va-search"><label for="va-query">${section==='users'?'Username or exact internal account ID':'Community name'}</label><div><input id="va-query" name="q" maxlength="100" value="${esc(query)}" autocomplete="off"><button class="vh-secondary" type="submit">Search</button></div></form>`:''}${section==='reports'?`<label class="vh-field">Report status<select id="va-report-filter">${[['open','Open'],['reviewing','Under review'],['resolved','Resolved'],['dismissed','Dismissed'],['all','All reports']].map(([value,label])=>`<option value="${value}" ${value===reportStatus?'selected':''}>${label}</option>`).join('')}</select></label>`:''}<p class="va-error" id="va-error" role="alert"></p><div id="va-results" class="va-results" role="status">Loading authorized records…</div></section>`;}
 async function open(next='users',pageOffset=0){
  sync();if(!identity)return;const current=guard();try{
   const data=await home.request('/api/admin/status');if(!current())return;ownerStatus=data;
   if(!data.isOwner)throw Error('This area is available only to the verified platform owner.');
   if(data.needsVerification){await stepUp();if(!current())return;}
   section=sections.some(([id])=>id===next)?next:'users';offset=Math.max(0,Number(pageOffset)||0);const ticket=++panel;
   home.showDialog('Platform administration','Actions are authorized by your immutable owner record and recorded in the audit trail.',layout());
   const generation=home.state.dialogGeneration,node=$('va-results');
   const search=new URLSearchParams({limit:'30',offset:String(offset)});if(query&&['users','communities'].includes(section))search.set('q',query);if(section==='reports')search.set('status',reportStatus);
   const result=await home.request('/api/admin/'+section+'?'+search);
   if(!current()||ticket!==panel||generation!==home.state.dialogGeneration||!node?.isConnected)return;
   node.innerHTML=content(result)+pager(result);
  }catch(error){if(current())fail(error);}
 }
 function content(data){
  if(section==='users')return data.users?.length?`<div class="va-table-wrap"><table><thead><tr><th>Account</th><th>Status / methods</th><th>Created</th><th>Actions</th></tr></thead><tbody>${data.users.map(a=>`<tr><td><b>${esc(a.displayName)}</b><span>@${esc(a.username||'deleted')}</span><code>${esc(a.id)}</code></td><td>${esc(a.status)}<span>${esc(a.methods.join(', ')||'No active authentication method')}</span><span>${a.verifiedEmail?'Verified recovery email':'No verified recovery email'}</span></td><td>${esc(date(a.createdAt))}</td><td class="va-row-actions">${a.id===identity?'<small>Current platform owner</small>':a.status==='deleted'?'<small>Retained reference only</small>':`<button class="vh-secondary" data-va-action="status-confirm" data-account="${esc(a.id)}" data-status="${a.status==='suspended'?'active':'suspended'}">${a.status==='suspended'?'Reinstate':'Suspend'}</button>`}<button class="vh-secondary" data-va-action="revoke-confirm" data-account="${esc(a.id)}">Revoke sessions</button><button class="vh-secondary" data-va-action="recovery" data-account="${esc(a.id)}">Recovery options</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="va-empty">No accounts match this search.</div>';
  if(section==='communities')return data.communities?.length?data.communities.map(c=>`<article class="va-record"><div><b>${esc(c.name)}</b><p>${esc(c.description)}</p><code>${esc(c.id)}</code><small>${Number(c.member_count)} members · Owner ${esc(c.owner_id||'unavailable')} · ${esc(date(c.created_at))}</small></div><button class="vh-secondary" data-va-action="community-confirm" data-community="${esc(c.id)}">Revoke all invitations</button></article>`).join(''):'<div class="va-empty">No communities match this search.</div>';
  if(section==='reports')return `<p class="va-note">${esc(data.contentDisclosure)}</p>`+(data.reports?.length?data.reports.map(r=>`<article class="va-record"><div><b>${esc(r.reason)}</b><small>${esc(r.target_type)} / ${esc(r.target_id)} · ${esc(r.status)} · ${esc(date(r.created_at))}</small><p class="va-report-detail">${esc(r.detail_text||'No additional content shared.')}</p><small>Reporter ${esc(r.reporter_id)}</small></div><button class="vh-secondary" data-va-action="report-review" data-report="${esc(r.id)}">Review report</button></article>`).join(''):'<div class="va-empty">No open reports.</div>');
  if(section==='catalog')return `<p class="va-note">Original gift designs remain free. Editing availability does not revoke existing ownership.</p>`+(data.gifts||[]).map(g=>`<article class="va-record"><div><b>${esc(g.name)}</b><p>${esc(g.description)}</p><small>${g.active===0?'Hidden from new claims':'Available'} · Free</small></div><button class="vh-secondary" data-va-action="catalog-edit" data-id="${esc(g.id)}" data-name="${esc(g.name)}" data-description="${esc(g.description)}" data-active="${g.active===0?'0':'1'}">Edit catalog entry</button></article>`).join('');
  if(section==='badges')return `<div class="va-toolbar"><p>Earned awards are distinct from free decorations and actual roles.</p><button class="vh-secondary" data-va-action="badge-create">Define reviewed badge</button></div>${(data.definitions||[]).map(b=>`<article class="va-record"><div><b>${esc(b.name)}</b><p>${esc(b.description)}</p><small>${esc(b.requirement)} · ${esc(b.rule)} · ${b.active?'Active':'Inactive'}</small></div>${b.active&&b.rule==='reviewed-contribution'?`<button class="vh-secondary" data-va-action="award-form" data-badge="${esc(b.id)}">Award after review</button>`:''}</article>`).join('')}`;
  if(section==='awards')return data.awards?.length?data.awards.map(a=>`<article class="va-record"><div><b>${esc(a.badge_id)}</b><code>${esc(a.account_id)}</code><small>${a.revoked_at?'Revoked '+esc(date(a.revoked_at)):'Awarded '+esc(date(a.issued_at))}</small><small>Issuer ${esc(a.issuer_id||'Authoritative server rule')}</small><p>${esc(a.reason)}</p></div>${!a.revoked_at?`<button class="vh-secondary" data-va-action="award-revoke" data-award="${esc(a.id)}">Revoke award</button>`:''}</article>`).join(''):'<div class="va-empty">No issued awards.</div>';
  if(section==='audit')return data.events?.length?data.events.map(e=>`<article class="va-record"><div><b>${esc(e.action)}</b><small>${esc(date(e.created_at))} · Actor ${esc(e.actor_id)}</small><code>${esc(e.target_type)} / ${esc(e.target_id)}</code><p>${esc(e.detail_json)}</p></div></article>`).join(''):'<div class="va-empty">No administrative actions recorded.</div>';
  return `<dl class="va-health"><div><dt>Database</dt><dd>${esc(data.database)}</dd></div><div><dt>Active accounts</dt><dd>${Number(data.accountCounts?.active)||0}</dd></div><div><dt>Suspended accounts</dt><dd>${Number(data.accountCounts?.suspended)||0}</dd></div><div><dt>Encrypted messaging service</dt><dd>${data.encryptionServiceConfigured?'Configured; separate acceptance tests required':'Not configured'}</dd></div><div><dt>Encrypted message contents</dt><dd>No owner decryption tool</dd></div><div><dt>Legacy text</dt><dd>Retained plaintext; outside this administration UI</dd></div><div><dt>Backup administration</dt><dd>Managed D1 provider; protected operator access required</dd></div></dl><p class="va-note">A healthy database does not verify a live encrypted exchange or a production backup restore. Use the documented isolated restore check.</p>`;
 }
 function form(title,copy,kind,fields,data={}){panel++;home.showDialog(title,copy,`<section class="va-panel"><form data-va-form="${kind}" ${Object.entries(data).map(([key,value])=>`data-${key}="${esc(value)}"`).join('')}><div class="va-fields">${fields}</div><p class="va-error" id="va-error" role="alert"></p><div class="va-actions"><button class="vh-primary" type="submit">Confirm</button><button class="vh-secondary" type="button" data-va-action="cancel">Cancel</button></div></form></section>`);}
 async function mutate(path,body,button,after){
  const current=guard(),ticket=panel,generation=home.state.dialogGeneration;if(button){button.disabled=true;button.setAttribute('aria-busy','true');}
  const valid=()=>current()&&ticket===panel&&generation===home.state.dialogGeneration&&(!button||button.isConnected);
  try{const data=await home.request('/api/admin/'+path,body);if(!valid())return;home.announce(data.delivery==='provider-accepted'?data.message:'Administrative change saved and audited.');if(after)await after(data);else await open(section,offset);}
  catch(error){if(valid())fail(error);}finally{if(current()&&button?.isConnected){button.disabled=false;button.removeAttribute('aria-busy');}}
 }
 function action(button){const d=button.dataset;
  if(d.vaAction==='section'){query='';return open(d.section);}
  if(d.vaAction==='page')return open(section,d.offset);
  if(d.vaAction==='cancel')return open(section,offset);
  if(d.vaAction==='copy-claim'){const node=$('va-owner-code');if(!navigator.clipboard?.writeText){node.focus();node.select();return;}return navigator.clipboard.writeText(node.value).then(()=>home.announce('Ownership request code copied.')).catch(()=>{node.focus();node.select();});}
  if(d.vaAction==='status-confirm')return form(d.status==='suspended'?'Suspend this account?':'Reinstate this account?','Existing sessions will be revoked. The reason is recorded in the audit trail.','account-status',`<label class="vh-field">Reason<textarea name="reason" minlength="5" maxlength="400" required rows="3"></textarea></label>`,{account:d.account,status:d.status});
  if(d.vaAction==='revoke-confirm')return form('Revoke account sessions?','This signs out the account on its devices. Your current owner session is retained unless explicitly included.','revoke-sessions','<label class="vh-check"><input name="includeCurrent" type="checkbox">Include my current session if this is my account</label>',{account:d.account});
  if(d.vaAction==='recovery')return form('Account recovery options','Recovery never reveals an existing password. Email delivery is available only through a configured verified channel.','recovery','<p>The user can recover with their own saved recovery method. No reset email will be fabricated if delivery is unavailable.</p>',{account:d.account});
  if(d.vaAction==='community-confirm')return form('Revoke every community invitation?','Current members retain membership. Future joins require a new invitation issued by the community.','community',`<label class="vh-field">Reason<textarea name="reason" minlength="5" maxlength="400" required rows="3"></textarea></label>`,{community:d.community});
  if(d.vaAction==='report-review')return form('Review this report','Only reporter-selected information is provided. This action does not decrypt a private conversation.','report','<label class="vh-field">Outcome<select name="status"><option value="reviewing">Under review</option><option value="resolved">Resolved</option><option value="dismissed">Dismissed</option></select></label><label class="vh-field">Review note<textarea name="reason" minlength="5" maxlength="400" required rows="3"></textarea></label>',{report:d.report});
  if(d.vaAction==='catalog-edit')return form('Edit an official gift','The item remains free. Existing owned instances retain their identity.','catalog',`<label class="vh-field">Name<input name="name" value="${esc(d.name)}" minlength="2" maxlength="60" required></label><label class="vh-field">Description<textarea name="description" minlength="2" maxlength="300" required rows="3">${esc(d.description)}</textarea></label><label class="vh-check"><input name="active" type="checkbox" ${d.active==='1'?'checked':''}>Available for new gifts and claims</label>`,{item:d.id});
  if(d.vaAction==='badge-create')return form('Define a reviewed achievement','A reviewed badge needs an explicit contribution requirement. It grants no permission role.','badge','<label class="vh-field">Stable ID<input name="id" pattern="[a-z][a-z0-9-]{2,47}" maxlength="48" required placeholder="community-contributor"></label><label class="vh-field">Name<input name="name" minlength="2" maxlength="60" required></label><label class="vh-field">Meaning<textarea name="description" minlength="5" maxlength="300" required></textarea></label><label class="vh-field">Legitimate requirement<textarea name="requirement" minlength="10" maxlength="500" required></textarea></label>');
  if(d.vaAction==='award-form')return form('Award after review','Confirm the immutable account ID and record the reviewed contribution.','award','<label class="vh-field">Account ID<input name="accountId" maxlength="100" required autocomplete="off"></label><label class="vh-field">Review evidence<textarea name="reason" minlength="10" maxlength="500" required rows="3"></textarea></label>',{badge:d.badge});
  if(d.vaAction==='award-revoke')return form('Revoke this earned award?','The original issuance remains in the administrative audit trail.','award-revoke','<label class="vh-field">Reason<textarea name="reason" minlength="10" maxlength="500" required rows="3"></textarea></label>',{award:d.award});
 }
 async function submit(formNode){if(formNode.dataset.busy)return;formNode.dataset.busy='1';const data=Object.fromEntries(new FormData(formNode)),d=formNode.dataset,button=formNode.querySelector('[type="submit"]');try{
  if(d.vaForm==='search'){query=data.q||'';return await open(section,0);}
  if(d.vaForm==='account-status')return await mutate('users/'+encode(d.account)+'/status',{status:d.status,reason:data.reason},button);
  if(d.vaForm==='revoke-sessions')return await mutate('users/'+encode(d.account)+'/revoke-sessions',{includeCurrent:data.includeCurrent==='on'},button);
  if(d.vaForm==='recovery')return await mutate('users/'+encode(d.account)+'/recovery',{},button);
  if(d.vaForm==='community')return await mutate('communities/'+encode(d.community)+'/revoke-invites',{reason:data.reason},button);
  if(d.vaForm==='report')return await mutate('reports/'+encode(d.report)+'/resolve',data,button);
  if(d.vaForm==='catalog')return await mutate('catalog/'+encode(d.item),{name:data.name,description:data.description,active:data.active==='on'},button);
  if(d.vaForm==='badge')return await mutate('badges/'+encode(data.id),{name:data.name,description:data.description,requirement:data.requirement,rule:'reviewed-contribution',active:true},button);
  if(d.vaForm==='award')return await mutate('badges/'+encode(d.badge)+'/award',data,button);
  if(d.vaForm==='award-revoke')return await mutate('awards/'+encode(d.award)+'/revoke',data,button);
 }finally{delete formNode.dataset.busy;}}
 const extension={id:'admin',init(bridge){if(home)return;home=bridge;sync();document.addEventListener('click',event=>{const button=event.target.closest('[data-va-action]');if(!button||!home.state.account)return;event.preventDefault();Promise.resolve(action(button)).catch(fail);});document.addEventListener('submit',event=>{if(!event.target.dataset.vaForm||!home.state.account)return;event.preventDefault();submit(event.target).catch(fail);});document.addEventListener('change',event=>{if(event.target.id==='va-report-filter'&&home.state.account){reportStatus=['open','reviewing','resolved','dismissed','all'].includes(event.target.value)?event.target.value:'open';open('reports',0);}});},navHTML,accountHTML,handles:name=>['admin-open','admin-owner-claim'].includes(name),handleAction(name){if(name==='admin-open'){open();return true;}if(name==='admin-owner-claim'){claim();return true;}return false;},onAccount(){sync();status();},onLock(){identity='';epoch++;panel++;ownerStatus=null;}};
 window.VoidAdmin=Object.freeze({extension,open,claim});
 function register(){window.VoidHome?.registerExtension?.(extension);}window.addEventListener('voidline:home-ready',register,{once:true});register();
})();
